import { useCallback, useState } from 'react';
import { JxButton, JxDivider, JxDrawer } from '@jinx-ui/react';

type NavKey = 'projects' | 'team' | 'settings' | 'logout';

type MenuDrawerProps = {
  onNavigate: (key: NavKey) => void;
};

const ITEMS: ReadonlyArray<{ key: NavKey; label: string }> = [
  { key: 'projects', label: 'Проекты' },
  { key: 'team', label: 'Команда' },
  { key: 'settings', label: 'Настройки' },
];

export default function MenuDrawer({ onNavigate }: MenuDrawerProps) {
  const [open, setOpen] = useState(false);

  const handleSelect = useCallback(
    (key: NavKey) => {
      onNavigate(key);
      setOpen(false);
    },
    [onNavigate],
  );

  return (
    <>
      <JxButton variant="primary" onClick={() => setOpen(true)}>
        Меню
      </JxButton>

      <JxDrawer
        open={open}
        onOpenChange={setOpen}
        side="left"
        title="Навигация"
      >
        <nav
          aria-label="Основная навигация"
          style={{
            display: 'flex',
            flexDirection: 'column',
            gap: 'var(--jx-space-2)',
            padding: 'var(--jx-space-2)',
          }}
        >
          {ITEMS.map((item) => (
            <JxButton
              key={item.key}
              variant="ghost"
              block
              onClick={() => handleSelect(item.key)}
            >
              {item.label}
            </JxButton>
          ))}

          <JxDivider />

          <JxButton
            variant="danger"
            block
            onClick={() => handleSelect('logout')}
          >
            Выйти
          </JxButton>
        </nav>
      </JxDrawer>
    </>
  );
}

